function LoadingGrid() {
  return <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">{[1, 2, 3, 4].map(i => <div key={i} className="overflow-hidden rounded-2xl border border-border bg-card"><div className="skeleton aspect-[.93]" /><div className="space-y-3 p-4"><div className="skeleton h-3 w-2/3 rounded" /><div className="skeleton h-5 w-4/5 rounded" /><div className="skeleton h-4 w-1/3 rounded" /></div></div>)}</div>;
}

function ErrorState({ retry, title = 'Something went sideways' }: { retry?: () => void; title?: string }) {
  return <div className="rounded-2xl border border-accent/20 bg-accent/5 px-6 py-12 text-center"><CircleAlert className="mx-auto text-accent" size={28} /><h3 className="mt-4 font-display text-xl font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">We could not load that just now. Give it another try, or come back in a moment.</p>{retry && <button type="button" data-testid="button-retry" onClick={retry} className="mt-5 rounded-full bg-primary px-5 py-2.5 text-sm font-bold text-primary-foreground hover:brightness-110">Try again</button>}</div>;
}

function EmptyState({ icon: Icon, title, copy, action }: { icon: typeof ShoppingBag; title: string; copy: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card px-6 py-16 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-secondary text-primary"><Icon size={25} /></span><h3 className="mt-5 font-display text-xl font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{copy}</p>{action && <div className="mt-6">{action}</div>}</div>;
}

function ImageFrame({ src, alt, className = '' }: { src?: string; alt: string; className?: string }) {
  return <div className={`relative overflow-hidden bg-secondary ${className}`}><img src={src || fallbackImage(alt)} alt={alt} className="h-full w-full object-cover transition-transform duration-500 hover:scale-[1.04]" onError={(e) => { e.currentTarget.src = fallbackImage(alt); }} /></div>;
}

function ProductCard({ product, onAdd }: { product: Product; onAdd?: (product: Product) => void }) {
  const variant = product.variants?.[0];
  return <div data-testid={`card-product-${product.id}`} className="group relative min-w-0">
    <Link href={`/product/${product.id}`} data-testid={`link-product-${product.id}`} className="block">
      <div className="relative overflow-hidden rounded-2xl border border-border bg-secondary/60">
        <ImageFrame src={product.imageUrl} alt={product.title} className="aspect-[.95]" />
        {product.badge && <span data-testid={`badge-product-${product.id}`} className="absolute left-3 top-3 rounded-full bg-accent px-2.5 py-1 font-mono text-[9px] font-bold uppercase tracking-[.12em] text-accent-foreground">{product.badge}</span>}
      </div>
      <div className="pt-3">
        <p className="truncate text-[11px] font-semibold uppercase tracking-[.08em] text-muted-foreground">{product.vendorName}</p>
        <h3 className="mt-1 truncate font-display text-[15px] font-bold leading-5">{product.title}</h3>
        <div className="mt-2 flex items-center gap-2"><span className="font-mono text-sm font-medium">{money(variant?.price ?? product.price, product.currency)}</span>{(variant?.compareAtPrice ?? product.compareAtPrice) && <span className="font-mono text-xs text-muted-foreground line-through">{money(variant?.compareAtPrice ?? product.compareAtPrice ?? 0, product.currency)}</span>}</div>
      </div>
    </Link>
    {onAdd && <button type="button" data-testid={`button-add-${product.id}`} onClick={() => onAdd(product)} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-primary/30 py-2.5 text-xs font-bold text-primary transition-all hover:bg-primary hover:text-primary-foreground active:scale-[.98]"><Plus size={15} /> Add to basket</button>}
  </div>;
}

function ProductStrip({ title, eyebrow, products, onAdd }: { title: string; eyebrow: string; products?: Product[]; onAdd?: (p: Product) => void }) {
  return <section className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="mb-5 flex items-end justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">{eyebrow}</p><h2 className="mt-1 font-display text-2xl font-bold tracking-[-.04em] sm:text-3xl">{title}</h2></div><Link href="/?view=all" data-testid={`link-see-all-${title.toLowerCase().replaceAll(' ', '-')}`} className="flex shrink-0 items-center gap-1 text-xs font-bold text-primary hover:gap-2">See all <ArrowRight size={14} /></Link></div>{products?.length ? <div className="grid grid-cols-2 gap-x-3 gap-y-7 sm:grid-cols-3 lg:grid-cols-4">{products.slice(0, 4).map(p => <ProductCard key={p.id} product={p} onAdd={onAdd} />)}</div> : <EmptyState icon={Package} title="A fresh shelf is coming" copy="We are curating something good for this collection." />}</section>;
}

function Home() {
  const [search, setSearch] = useState('');
  const [submitted, setSubmitted] = useState('');
  const [location, setLocation] = useLocation();
  const summary = useGetCatalogSummary({ query: { queryKey: getGetCatalogSummaryQueryKey() } });
  const categories = useListCategories({ query: { queryKey: getListCategoriesQueryKey() } });
  const params = useMemo(() => submitted ? { search: submitted, limit: 20 } : undefined, [submitted]);
  const results = useListProducts(params, { query: { queryKey: getListProductsQueryKey(params), enabled: !!submitted } });
  const add = useAddCartItem();
  const { toast } = useToast();
  const addToCart = (product: Product) => {
    const variant = product.variants?.[0];
    if (!variant) return;
    add.mutate({ data: { productId: product.id, variantId: variant.id, quantity: 1 } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetCartQueryKey() }); toast({ title: 'Added to your basket', description: product.title }); }, onError: () => toast({ title: 'Could not add that item', description: 'Please try again.', variant: 'destructive' }) });
  };
  const submitSearch = (e: React.FormEvent) => { e.preventDefault(); setSubmitted(search.trim()); if (search.trim()) setLocation(`/?search=${encodeURIComponent(search.trim())}`); };
  return <div>
    <section className="relative overflow-hidden bg-primary text-primary-foreground">
      <div className="absolute -right-20 -top-20 h-72 w-72 rounded-full border-[38px] border-accent/40 sm:h-96 sm:w-96" />
      <div className="absolute bottom-[-110px] left-[28%] h-64 w-64 rounded-full border-[24px] border-primary-foreground/10" />
      <div className="relative mx-auto grid max-w-7xl gap-10 px-4 pb-14 pt-12 sm:px-6 sm:pb-20 sm:pt-16 lg:grid-cols-[1.05fr_.95fr] lg:items-center lg:px-8 lg:py-20">
        <div className="animate-rise"><p className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.23em] text-primary-foreground/65"><MapPin size={13} /> Independent sellers, everywhere</p><h1 className="mt-5 max-w-xl font-display text-5xl font-bold leading-[.95] tracking-[-.07em] sm:text-7xl">Good things, <span className="text-accent">worth finding.</span></h1><p className="mt-6 max-w-md text-sm leading-6 text-primary-foreground/75 sm:text-base">A trusted basket of local finds and international discoveries, sourced with care and delivered to you.</p>
          <form onSubmit={submitSearch} className="mt-8 flex max-w-lg items-center gap-2 rounded-2xl bg-background p-2 text-foreground shadow-md"><Search className="ml-2 text-muted-foreground" size={19} /><input data-testid="input-home-search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search products or vendors" className="min-w-0 flex-1 bg-transparent px-2 py-2 text-sm outline-none" /><button type="submit" data-testid="button-home-search" className="rounded-xl bg-accent px-4 py-2.5 text-xs font-bold text-accent-foreground hover:brightness-110">Search</button></form>
          <div className="mt-6 flex flex-wrap gap-x-5 gap-y-2 text-xs text-primary-foreground/70"><span className="flex items-center gap-1.5"><ShieldCheck size={14} /> Verified vendors</span><span className="flex items-center gap-1.5"><Bike size={14} /> 1–2 day delivery</span></div>
        </div>
        <div className="relative hidden min-h-[340px] lg:block"><div className="absolute right-12 top-4 h-64 w-64 rotate-6 rounded-[38px] bg-accent shadow-2xl shadow-black/20" /><div className="absolute right-24 top-12 h-64 w-64 -rotate-6 overflow-hidden rounded-[38px] border-[10px] border-background/80 bg-secondary"><ImageFrame src={summary.data?.featured?.[0]?.imageUrl} alt="Gulani product selection" className="h-full w-full" /></div><div className="absolute bottom-6 left-6 rounded-2xl bg-background p-4 text-foreground shadow-xl"><p className="font-mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">New on Gulani</p><p className="mt-1 font-display text-lg font-bold">Worth finding.</p><span className="mt-2 flex items-center gap-1 text-xs font-semibold text-primary"><TrendingUp size={13} /> New picks daily</span></div></div>
      </div>
    </section>
    <div className="border-b border-border bg-secondary/50"><div className="mx-auto flex max-w-7xl items-center gap-3 overflow-x-auto px-4 py-3 text-xs font-semibold sm:px-6 lg:px-8"><span className="shrink-0 font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Browse by mood</span>{(categories.data || summary.data?.categories || []).slice(0, 6).map(c => <button type="button" key={c.id} data-testid={`button-category-${c.slug}`} onClick={() => { setSubmitted(c.name); setSearch(c.name); }} className="shrink-0 rounded-full border border-border bg-background px-3 py-1.5 hover:border-primary hover:text-primary">{c.name}</button>)}</div></div>
    {submitted ? <section className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="mb-6 flex items-end justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Search results</p><h2 data-testid="text-search-title" className="mt-1 font-display text-3xl font-bold">For “{submitted}”</h2></div><button type="button" data-testid="button-clear-search" onClick={() => { setSubmitted(''); setSearch(''); setLocation('/'); }} className="text-xs font-bold text-primary">Clear search</button></div>{results.isLoading ? <LoadingGrid /> : results.isError ? <ErrorState retry={() => results.refetch()} /> : results.data?.length ? <div className="grid grid-cols-2 gap-x-3 gap-y-8 sm:grid-cols-3 lg:grid-cols-4">{results.data.map(p => <ProductCard key={p.id} product={p} onAdd={addToCart} />)}</div> : <EmptyState icon={Search} title="No exact matches yet" copy="Try a broader search, or explore the shelves below." action={<button type="button" data-testid="button-browse-featured" onClick={() => { setSubmitted(''); setSearch(''); }} className="rounded-full bg-primary px-5 py-2.5 text-xs font-bold text-primary-foreground">Browse featured</button>} />}</section> : <>
      <ProductStrip eyebrow="Picked for you" title="Featured right now" products={summary.data?.featured} onAdd={addToCart} />
      <section className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8"><div className="rounded-[28px] bg-secondary px-6 py-8 sm:flex sm:items-center sm:justify-between sm:px-10 sm:py-10"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">The Gulani promise</p><h2 className="mt-2 max-w-xl font-display text-2xl font-bold tracking-[-.04em] sm:text-3xl">Every order connects you with a trusted seller.</h2></div><div className="mt-6 grid grid-cols-3 gap-5 sm:mt-0"><div><p className="font-display text-2xl font-bold text-primary">01</p><p className="mt-1 text-xs leading-4 text-muted-foreground">Verified sellers</p></div><div><p className="font-display text-2xl font-bold text-primary">02</p><p className="mt-1 text-xs leading-4 text-muted-foreground">Clear sourcing</p></div><div><p className="font-display text-2xl font-bold text-primary">03</p><p className="mt-1 text-xs leading-4 text-muted-foreground">Safe payment</p></div></div></div></section>
      <ProductStrip eyebrow="Moving fast" title="Trending around town" products={summary.data?.trending} onAdd={addToCart} />
      <section className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="mb-5"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Find your next</p><h2 className="mt-1 font-display text-2xl font-bold tracking-[-.04em]">Shop by category</h2></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{(categories.data || summary.data?.categories || []).slice(0, 8).map((c, i) => <button type="button" key={c.id} data-testid={`card-category-${c.id}`} onClick={() => { setSearch(c.name); setSubmitted(c.name); }} className={`group relative min-h-32 overflow-hidden rounded-2xl p-4 text-left ${i % 3 === 0 ? 'bg-primary text-primary-foreground' : i % 3 === 1 ? 'bg-accent text-accent-foreground' : 'bg-secondary text-foreground'}`}><span className="relative z-10 font-display text-lg font-bold leading-5">{c.name}</span><span className="relative z-10 mt-2 block font-mono text-[10px] uppercase tracking-[.12em] opacity-70">{c.productCount} finds</span><ArrowUpRight className="absolute bottom-3 right-3 transition-transform group-hover:translate-x-1 group-hover:-translate-y-1" size={18} /></button>)}</div></section>
    </>}
    {!summary.isLoading && !summary.data && <div className="mx-auto max-w-7xl px-4 pb-10 sm:px-6 lg:px-8"><ErrorState retry={() => summary.refetch()} /></div>}
  </div>;
}

function ArrowUpRight({ className, size }: { className?: string; size?: number }) { return <ArrowRight size={size} className={`${className || ''} -rotate-45`} />; }

function ScrollToTop() {
  const [location] = useLocation();

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [location]);

  useEffect(() => {
    const previousRestoration = window.history.scrollRestoration;
    window.history.scrollRestoration = 'manual';
    return () => {
      window.history.scrollRestoration = previousRestoration;
    };
  }, []);

  return null;
}

function ProductDetail() {
  const { id = '' } = useParams<{ id: string }>();
  const product = useGetProduct(id, { query: { queryKey: getGetProductQueryKey(id), enabled: !!id } });
  const [selected, setSelected] = useState<ProductVariant | undefined>();
  const [quantity, setQuantity] = useState(1);
  const [location, setLocation] = useLocation();
  const { toast } = useToast();
  const add = useAddCartItem();
  const p = product.data;
  const variant = selected || p?.variants?.[0];
  if (product.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8"><LoadingGrid /></div>;
  if (product.isError || !p) return <div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><ErrorState title="This product is not on the shelf" retry={() => product.refetch()} /></div>;
  const addItem = () => { if (!variant) return; add.mutate({ data: { productId: p.id, variantId: variant.id, quantity } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetCartQueryKey() }); toast({ title: 'Added to your basket', description: `${quantity} × ${p.title}` }); }, onError: () => toast({ title: 'Could not add that item', variant: 'destructive' }) }); };
  return <div className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8"><Link href="/" className="mb-8 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft size={15} /> Back to discover</Link><div className="grid gap-10 lg:grid-cols-[1.02fr_.98fr] lg:gap-16"><div className="overflow-hidden rounded-[28px] bg-secondary"><ImageFrame src={p.imageUrl} alt={p.title} className="aspect-square sm:aspect-[1.06]" /></div><div className="flex flex-col justify-center"><div className="flex items-center gap-2"><span className="rounded-full bg-secondary px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-[.14em] text-primary">{p.category}</span>{p.source && p.source !== 'local-vendors' && <span className="rounded-full bg-primary/10 px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-[.14em] text-primary">Sourced via {p.source}</span>}</div><h1 className="mt-5 max-w-xl font-display text-4xl font-bold leading-[1.02] tracking-[-.06em] sm:text-5xl">{p.title}</h1><div className="mt-4 flex items-center gap-3 text-sm"><Star size={15} className="fill-accent text-accent" /><span className="font-bold">{p.vendorRating.toFixed(1)}</span><span className="text-muted-foreground">from</span><span className="font-bold text-primary">{p.vendorName}</span></div><p className="mt-7 max-w-xl text-sm leading-7 text-muted-foreground">{p.description}</p>{p.variants?.length > 0 && <div className="mt-8"><div className="mb-3 flex justify-between"><p className="text-xs font-bold uppercase tracking-[.12em]">Choose an option</p><p className="font-mono text-[10px] text-muted-foreground">{variant?.stockQty} available</p></div><div className="flex flex-wrap gap-2">{p.variants.map(v => <button type="button" key={v.id} onClick={() => setSelected(v)} className={`rounded-xl border px-4 py-3 text-left text-sm font-semibold ${variant?.id === v.id ? 'border-primary bg-primary/10 text-primary' : 'border-border'}`}><span className="block">{v.name}</span><span className="mt-1 block font-mono text-xs font-normal">{money(v.price, p.currency)}</span></button>)}</div></div>}<div className="mt-9 flex flex-wrap gap-3"><div className="flex items-center rounded-xl border border-border"><button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="grid h-12 w-11 place-items-center hover:bg-secondary"><Minus size={16} /></button><span className="w-8 text-center font-mono text-sm">{quantity}</span><button type="button" onClick={() => setQuantity(Math.min(20, quantity + 1))} className="grid h-12 w-11 place-items-center hover:bg-secondary"><Plus size={16} /></button></div><button type="button" disabled={add.isPending || !variant?.stockQty} onClick={addItem} className="flex min-h-12 flex-1 items-center justify-center gap-2 rounded-xl bg-primary px-6 text-sm font-bold text-primary-foreground disabled:opacity-60 sm:flex-none">{add.isPending ? 'Adding…' : <><ShoppingBag size={17} /> Add to basket · {money((variant?.price || p.price) * quantity, p.currency)}</>}</button></div><button type="button" onClick={() => { addItem(); setLocation('/cart'); }} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-primary py-3 text-sm font-bold text-primary hover:bg-primary/5"><Zap size={16} /> Buy this, delivered to you</button><div className="mt-8 grid grid-cols-2 gap-3 border-t border-border pt-6 text-xs text-muted-foreground"><span className="flex items-center gap-2"><Truck size={16} className="text-primary" /> Delivery available</span><span className="flex items-center gap-2"><BadgeCheck size={16} className="text-primary" /> Trusted seller</span></div></div></div></div>;
}

function LegacyProductDetail() {
  const { id = '' } = useParams<{ id: string }>();
  const product = useGetProduct(id, { query: { queryKey: getGetProductQueryKey(id), enabled: !!id } });
  const [selected, setSelected] = useState<ProductVariant | undefined>();
  const [quantity, setQuantity] = useState(1);
  const [location, setLocation] = useLocation();
  const { toast } = useToast();
  const add = useAddCartItem();
  const p = product.data;
  const variant = selected || p?.variants?.[0];
  if (product.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8"><LoadingGrid /></div>;
  if (product.isError || !p) return <div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><ErrorState title="This product is not on the shelf" retry={() => product.refetch()} /></div>;
  const addItem = () => { if (!variant) return; add.mutate({ data: { productId: p.id, variantId: variant.id, quantity } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetCartQueryKey() }); toast({ title: 'Added to your basket', description: `${quantity} × ${p.title}` }); }, onError: () => toast({ title: 'Could not add that item', variant: 'destructive' }) }); };
  return <div className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8"><Link href="/" data-testid="link-back-store" className="mb-8 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft size={15} /> Back to discover</Link><div className="grid gap-10 lg:grid-cols-[1.02fr_.98fr] lg:gap-16"><div className="overflow-hidden rounded-[28px] bg-secondary"><ImageFrame src={p.imageUrl} alt={p.title} className="aspect-square sm:aspect-[1.06]" /></div><div className="flex flex-col justify-center"><div className="flex items-center gap-2"><span className="rounded-full bg-secondary px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-[.14em] text-primary">{p.category}</span>{p.badge && <span className="rounded-full bg-accent px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-[.14em] text-accent-foreground">{p.badge}</span>}</div><h1 data-testid="text-product-title" className="mt-5 max-w-xl font-display text-4xl font-bold leading-[1.02] tracking-[-.06em] sm:text-5xl">{p.title}</h1><div className="mt-4 flex items-center gap-3 text-sm"><span className="flex items-center gap-1 font-bold"><Star size={15} className="fill-accent text-accent" /> {p.vendorRating.toFixed(1)}</span><span className="text-muted-foreground">from</span><span className="font-bold text-primary">{p.vendorName}</span></div><p className="mt-7 max-w-xl text-sm leading-7 text-muted-foreground">{p.description}</p>{p.variants?.length > 0 && <div className="mt-8"><div className="mb-3 flex justify-between"><p className="text-xs font-bold uppercase tracking-[.12em]">Choose an option</p><p className="font-mono text-[10px] text-muted-foreground">{variant?.stockQty} available</p></div><div className="flex flex-wrap gap-2">{p.variants.map(v => <button type="button" key={v.id} data-testid={`button-variant-${v.id}`} onClick={() => setSelected(v)} className={`rounded-xl border px-4 py-3 text-left text-sm font-semibold transition-colors ${variant?.id === v.id ? 'border-primary bg-primary/10 text-primary' : 'border-border hover:border-primary/50'}`}><span className="block">{v.name}</span><span className="mt-1 block font-mono text-xs font-normal">{money(v.price, p.currency)}</span></button>)}</div></div>}<div className="mt-9 flex flex-wrap gap-3"><div className="flex items-center rounded-xl border border-border"><button type="button" data-testid="button-quantity-decrease" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="grid h-12 w-11 place-items-center hover:bg-secondary"><Minus size={16} /></button><span data-testid="text-product-quantity" className="w-8 text-center font-mono text-sm">{quantity}</span><button type="button" data-testid="button-quantity-increase" onClick={() => setQuantity(Math.min(20, quantity + 1))} className="grid h-12 w-11 place-items-center hover:bg-secondary"><Plus size={16} /></button></div><button type="button" data-testid="button-product-add" disabled={add.isPending || !variant?.stockQty} onClick={addItem} className="flex min-h-12 flex-1 items-center justify-center gap-2 rounded-xl bg-primary px-6 text-sm font-bold text-primary-foreground transition-all hover:brightness-110 active:scale-[.98] disabled:opacity-60 sm:flex-none">{add.isPending ? 'Adding…' : <><ShoppingBag size={17} /> Add to basket · {money((variant?.price || p.price) * quantity, p.currency)}</>}</button></div><button type="button" data-testid="button-buy-now" onClick={() => { addItem(); setLocation('/cart'); }} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-primary py-3 text-sm font-bold text-primary hover:bg-primary/5"><Zap size={16} /> Buy this, delivered to Lusaka</button><div className="mt-8 grid grid-cols-2 gap-3 border-t border-border pt-6 text-xs text-muted-foreground"><span className="flex items-center gap-2"><Truck size={16} className="text-primary" /> Lusaka delivery</span><span className="flex items-center gap-2"><BadgeCheck size={16} className="text-primary" /> Trusted vendor</span></div></div></div></div>;
}

function CartPage() {
  const cart = useGetCart({ query: { queryKey: getGetCartQueryKey() } });
  const update = useUpdateCartItem();
  const remove = useRemoveCartItem();
  const { toast } = useToast();
  const applyCart = (next: Cart) => queryClient.setQueryData(getGetCartQueryKey(), next);
  if (cart.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8"><LoadingGrid /></div>;
  if (cart.isError) return <div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><ErrorState retry={() => cart.refetch()} /></div>;
  const data = cart.data;
  if (!data?.items?.length) return <div className="mx-auto max-w-3xl px-4 py-14 sm:px-6"><div className="mb-8"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Your basket</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">A little space for good things.</h1></div><EmptyState icon={ShoppingBag} title="Your basket is waiting" copy="Find something made or sourced with care and it will show up here." action={<Link href="/" data-testid="link-empty-cart-shop" className="inline-flex rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Start discovering</Link>} /></div>;
  const adjust = (item: CartItem, quantity: number) => update.mutate({ itemId: item.id, data: { quantity } }, { onSuccess: applyCart, onError: () => toast({ title: 'Could not update basket', variant: 'destructive' }) });
  const removeItem = (item: CartItem) => remove.mutate({ itemId: item.id }, { onSuccess: applyCart, onError: () => toast({ title: 'Could not remove item', variant: 'destructive' }) });
  const vendors = Array.from(new Set(data.items.map(i => i.vendorName)));
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="mb-9 flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Your basket · {data.items.length} items</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">Ready when you are.</h1></div><Link href="/" data-testid="link-cart-continue" className="flex items-center gap-1 text-xs font-bold text-primary">Keep shopping <ArrowRight size={14} /></Link></div><div className="grid gap-8 lg:grid-cols-[1fr_360px]"><div className="space-y-6">{vendors.map(vendor => <section key={vendor} className="rounded-2xl border border-border bg-card p-4 sm:p-6"><div className="mb-5 flex items-center gap-2 border-b border-border pb-4"><Store size={16} className="text-primary" /><h2 className="text-sm font-bold">{vendor}</h2><span className="ml-auto font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Verified shop</span></div><div className="space-y-5">{data.items.filter(i => i.vendorName === vendor).map(item => <div key={item.id} data-testid={`row-cart-item-${item.id}`} className="flex gap-3"><ImageFrame src={item.imageUrl} alt={item.title} className="h-20 w-20 shrink-0 rounded-xl" /><div className="min-w-0 flex-1"><h3 className="truncate text-sm font-bold">{item.title}</h3><p className="mt-1 text-xs text-muted-foreground">{item.variantName}</p><p className="mt-2 font-mono text-sm">{money(item.unitPrice)}</p></div><div className="flex flex-col items-end justify-between"><button type="button" data-testid={`button-remove-${item.id}`} aria-label={`Remove ${item.title}`} onClick={() => removeItem(item)} className="text-muted-foreground hover:text-destructive"><Trash2 size={15} /></button><div className="flex items-center rounded-lg border border-border"><button type="button" data-testid={`button-decrease-${item.id}`} onClick={() => item.quantity > 1 ? adjust(item, item.quantity - 1) : removeItem(item)} className="grid h-7 w-7 place-items-center hover:bg-secondary"><Minus size={12} /></button><span data-testid={`text-quantity-${item.id}`} className="w-7 text-center font-mono text-xs">{item.quantity}</span><button type="button" data-testid={`button-increase-${item.id}`} onClick={() => adjust(item, Math.min(20, item.quantity + 1))} className="grid h-7 w-7 place-items-center hover:bg-secondary"><Plus size={12} /></button></div></div></div>)}</div></section>)}</div><aside className="h-fit rounded-2xl border border-border bg-card p-5 sm:p-6 lg:sticky lg:top-24"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Lusaka delivery estimate</p><div className="mt-3 flex items-start gap-3 rounded-xl bg-secondary p-3"><Truck className="mt-0.5 shrink-0 text-primary" size={18} /><p className="text-xs leading-5">Arrives in <strong>1–2 business days</strong>. We will confirm your exact fee at checkout.</p></div><div className="mt-6 space-y-3 border-b border-border pb-5 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Basket subtotal</span><span data-testid="text-cart-subtotal" className="font-mono">{money(data.subtotal, data.currency)}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Delivery</span><span className="font-mono">{money(data.deliveryFee, data.currency)}</span></div></div><div className="flex justify-between pt-5"><span className="font-bold">Total</span><span data-testid="text-cart-total" className="font-mono text-lg font-bold">{money(data.total, data.currency)}</span></div><Link href="/checkout" data-testid="link-cart-checkout" className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground hover:brightness-110">Continue to checkout <ArrowRight size={16} /></Link><p className="mt-3 text-center text-[11px] text-muted-foreground">Paid delivery only · no cash on delivery</p></aside></div></div>;
}

function CheckoutPage() {
  const cart = useGetCart({ query: { queryKey: getGetCartQueryKey() } });
  const checkout = useCreateCheckout();
  const [location, setLocation] = useLocation();
  const [payment, setPayment] = useState<string>(CheckoutInputPaymentMethod.mtn_mobile_money);
  const [form, setForm] = useState({ fullName: '', email: '', phone: '', address: '', paymentPhone: '' });
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setForm({ ...form, [key]: e.target.value });
  if (cart.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8"><LoadingGrid /></div>;
  if (!cart.data?.items?.length) return <div className="mx-auto max-w-3xl px-4 py-14 sm:px-6"><EmptyState icon={ShoppingBag} title="Your basket is empty" copy="Add something beautiful before you head to checkout." action={<Link href="/" data-testid="link-checkout-empty" className="inline-flex rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Back to discovery</Link>} /></div>;
  const submit = (e: React.FormEvent) => { e.preventDefault(); setSubmitted(true); setError(''); if (!form.fullName.trim() || !form.email.includes('@') || form.phone.trim().length < 7 || form.address.trim().length < 5 || ((payment !== 'visa') && form.paymentPhone.trim().length < 7)) { setError('Please check the highlighted details before continuing.'); return; } const data: CheckoutInput = { ...form, deliveryZone: 'global', paymentMethod: payment as CheckoutInput['paymentMethod'], paymentPhone: payment === 'visa' ? null : form.paymentPhone }; checkout.mutate({ data }, { onSuccess: (result) => { if (result.paymentStatus === 'failed') { setError('Payment did not go through. Check your details and try again.'); return; } setLocation(`/order/${result.orderId}`); }, onError: () => setError('We could not start the payment. Please try again.') }); };
  const field = (key: keyof typeof form, label: string, type = 'text', placeholder = '') => <label className="grid gap-2 text-xs font-bold">{label}<input data-testid={`input-checkout-${key}`} type={type} value={form[key]} onChange={update(key)} placeholder={placeholder} className={`h-11 rounded-xl border bg-background px-3 text-sm font-normal outline-none transition-colors focus:border-primary focus:ring-2 focus:ring-primary/10 ${submitted && (!form[key] || (key === 'email' && !form.email.includes('@')) || (key === 'phone' && form.phone.length < 7)) ? 'border-accent' : 'border-input'}`} /></label>;
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><Link href="/cart" data-testid="link-checkout-back" className="mb-8 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft size={15} /> Back to basket</Link><div className="grid gap-10 lg:grid-cols-[1fr_360px]"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Almost there</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">A good delivery starts here.</h1><p className="mt-3 text-sm text-muted-foreground">Guest checkout · we only ask for what gets your order to you.</p>{error && <div data-testid="status-checkout-error" className="mt-6 flex items-start gap-3 rounded-xl border border-accent/30 bg-accent/10 p-4 text-sm"><CircleAlert className="shrink-0 text-accent" size={18} /><span>{error}</span></div>}<form onSubmit={submit} className="mt-8 space-y-8"><section><h2 className="font-display text-xl font-bold">Your details</h2><div className="mt-4 grid gap-4 sm:grid-cols-2">{field('fullName', 'Full name', 'text', 'e.g. Naledi Mwape')}{field('email', 'Email address', 'email', 'you@example.com')}{field('phone', 'Phone number', 'tel', '+260 97 000 0000')}</div></section><section><h2 className="font-display text-xl font-bold">Where should we deliver?</h2><div className="mt-4 grid gap-4"><label className="grid gap-2 text-xs font-bold">Lusaka address<textarea data-testid="input-checkout-address" value={form.address} onChange={update('address')} placeholder="Plot, street, neighbourhood and a useful landmark" rows={4} className={`resize-none rounded-xl border bg-background px-3 py-3 text-sm font-normal outline-none focus:border-primary focus:ring-2 focus:ring-primary/10 ${submitted && form.address.length < 5 ? 'border-accent' : 'border-input'}`} /></label><div className="flex items-center gap-2 text-xs text-muted-foreground"><MapPin size={14} className="text-primary" /> Currently delivering across Lusaka.</div></div></section><section><h2 className="font-display text-xl font-bold">How would you like to pay?</h2><div className="mt-4 grid gap-3 sm:grid-cols-3">{[{value: CheckoutInputPaymentMethod.mtn_mobile_money, label: 'MTN Mobile Money', short: 'MTN'}, {value: CheckoutInputPaymentMethod.airtel_money, label: 'Airtel Money', short: 'Airtel'}, {value: CheckoutInputPaymentMethod.visa, label: 'Visa card', short: 'VISA'}].map(option => <button type="button" key={option.value} data-testid={`button-payment-${option.value}`} onClick={() => setPayment(option.value)} className={`rounded-xl border p-4 text-left transition-colors ${payment === option.value ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'}`}><span className={`font-mono text-[10px] font-bold ${payment === option.value ? 'text-primary' : 'text-muted-foreground'}`}>{option.short}</span><span className="mt-2 block text-xs font-bold">{option.label}</span>{payment === option.value && <Check size={15} className="mt-2 text-primary" />}</button>)}</div>{payment !== 'visa' && <div className="mt-4 max-w-sm">{field('paymentPhone', 'Mobile Money number', 'tel', 'Number to charge')}</div>}<p className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck size={15} className="text-primary" /> Your payment is processed securely.</p></section><button type="submit" data-testid="button-place-order" disabled={checkout.isPending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-4 text-sm font-bold text-primary-foreground hover:brightness-110 disabled:opacity-60">{checkout.isPending ? 'Connecting to payment…' : <>Place paid order <ArrowRight size={16} /></>}</button></form></div><aside className="h-fit rounded-2xl border border-border bg-card p-5 sm:p-6 lg:sticky lg:top-24"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Order summary</p><div className="mt-5 space-y-4">{cart.data.items.map(item => <div key={item.id} className="flex gap-3"><ImageFrame src={item.imageUrl} alt={item.title} className="h-14 w-14 shrink-0 rounded-lg" /><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{item.title}</p><p className="mt-1 text-[11px] text-muted-foreground">{item.quantity} × {item.variantName}</p></div><span className="font-mono text-xs">{money(item.unitPrice * item.quantity, cart.data.currency)}</span></div>)}</div><div className="mt-5 space-y-3 border-t border-border pt-5 text-sm"><div className="flex justify-between text-muted-foreground"><span>Subtotal</span><span className="font-mono">{money(cart.data.subtotal, cart.data.currency)}</span></div><div className="flex justify-between text-muted-foreground"><span>Delivery</span><span className="font-mono">{money(cart.data.deliveryFee, cart.data.currency)}</span></div><div className="flex justify-between pt-2 font-bold"><span>Total</span><span className="font-mono">{money(cart.data.total, cart.data.currency)}</span></div></div></aside></div></div>;
}

function OrderTimeline({ status }: { status: string }) {
  const states = [{ label: 'Order placed', copy: 'We have your request', icon: Check }, { label: 'Being prepared', copy: 'Your vendors are on it', icon: Package }, { label: 'On its way', copy: 'A rider is bringing it over', icon: Bike }, { label: 'Delivered', copy: 'Enjoy your finds', icon: BadgeCheck }];
  const normalized = status.toLowerCase(); const current = normalized.includes('deliver') ? 3 : normalized.includes('ship') || normalized.includes('way') ? 2 : normalized.includes('prepare') || normalized.includes('process') ? 1 : 0;
  return <div className="relative mt-8 space-y-0">{states.map(({ label, copy, icon: Icon }, i) => <div key={label} className="relative flex gap-4 pb-8 last:pb-0"><div className={`relative z-10 grid h-9 w-9 shrink-0 place-items-center rounded-full border-2 ${i <= current ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background text-muted-foreground'}`}>{i < current ? <Check size={15} /> : <Icon size={15} />}</div>{i < states.length - 1 && <div className={`absolute left-[17px] top-9 h-full w-0.5 ${i < current ? 'bg-primary' : 'bg-border'}`} />}<div className="pt-1"><p className={`text-sm font-bold ${i <= current ? 'text-foreground' : 'text-muted-foreground'}`}>{label}</p><p className="mt-1 text-xs text-muted-foreground">{copy}</p></div></div>)}</div>;
}

function OrderPage() {
  const { id = '' } = useParams<{ id: string }>();
  const order = useGetOrder(id, { query: { queryKey: getGetOrderQueryKey(id), enabled: !!id } });
  const o = order.data;
  if (order.isLoading) return <div className="mx-auto max-w-3xl px-4 py-14 sm:px-6"><div className="skeleton mx-auto h-16 w-16 rounded-full" /><div className="skeleton mx-auto mt-6 h-8 w-64 rounded" /></div>;
  if (order.isError || !o) return <div className="mx-auto max-w-3xl px-4 py-14 sm:px-6"><ErrorState title="We could not find that order" retry={() => order.refetch()} /></div>;
  return <div className="mx-auto max-w-4xl px-4 py-10 sm:px-6 lg:px-8"><div className="text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-primary text-primary-foreground"><Check size={31} /></span><p className="mt-6 font-mono text-[10px] uppercase tracking-[.2em] text-accent">Order confirmed</p><h1 data-testid="text-order-confirmation" className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">Thank you, {o.deliveryAddress.split(',')[0] || 'Lusaka'}.</h1><p className="mt-3 text-sm text-muted-foreground">Your order <span className="font-mono font-bold text-foreground">{o.orderNumber}</span> is in good hands.</p></div><div className="mt-10 grid gap-6 lg:grid-cols-[1fr_300px]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between border-b border-border pb-5"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Fulfillment timeline</p><p data-testid="status-order" className="mt-2 text-sm font-bold capitalize">{o.status}</p></div><Clock3 size={22} className="text-primary" /></div><OrderTimeline status={o.status} /></section><aside className="space-y-5"><div className="rounded-2xl bg-secondary p-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Paid total</p><p data-testid="text-order-total" className="mt-2 font-mono text-2xl font-bold">{money(o.total, o.currency)}</p><p className="mt-4 flex gap-2 text-xs leading-5 text-muted-foreground"><MapPin size={15} className="shrink-0 text-primary" />{o.deliveryAddress}</p></div><div className="rounded-2xl border border-border bg-card p-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Items</p><div className="mt-4 space-y-4">{o.items.map(item => <div key={item.id} className="flex gap-3"><ImageFrame src={item.imageUrl} alt={item.title} className="h-12 w-12 shrink-0 rounded-lg" /><div className="min-w-0"><p className="truncate text-xs font-bold">{item.title}</p><p className="mt-1 text-[11px] text-muted-foreground">{item.quantity} × {money(item.unitPrice, o.currency)}</p></div></div>)}</div></div></aside></div><div className="mt-8 flex flex-wrap justify-center gap-3"><Link href="/" data-testid="link-order-shop-more" className="rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Keep discovering</Link><Link href="/orders" data-testid="link-order-history" className="rounded-full border border-primary px-5 py-3 text-xs font-bold text-primary">View your orders</Link></div></div>;
}

function OrdersPage() {
  const orders = useListOrders({ query: { queryKey: getListOrdersQueryKey() } });
  if (orders.isLoading) return <div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><LoadingGrid /></div>;
  if (orders.isError) return <div className="mx-auto max-w-4xl px-4 py-14 sm:px-6"><ErrorState retry={() => orders.refetch()} /></div>;
  return <div className="mx-auto max-w-4xl px-4 py-10 sm:px-6 lg:px-8"><div className="mb-9"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Your account</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">Orders, in one place.</h1><p className="mt-3 text-sm text-muted-foreground">Track deliveries and revisit what you loved.</p></div>{orders.data?.length ? <div className="space-y-3">{orders.data.map(order => <Link key={order.id} href={`/order/${order.id}`} data-testid={`row-order-${order.id}`} className="group flex flex-col gap-4 rounded-2xl border border-border bg-card p-4 transition-all hover:border-primary/40 hover:shadow-sm sm:flex-row sm:items-center sm:p-5"><div className="flex -space-x-3">{order.items.slice(0, 3).map(item => <ImageFrame key={item.id} src={item.imageUrl} alt={item.title} className="h-12 w-12 rounded-xl border-2 border-card" />)}</div><div className="min-w-0 flex-1"><p className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">{order.orderNumber}</p><p className="mt-1 text-sm font-bold">{order.items.length} {order.items.length === 1 ? 'item' : 'items'} · {new Date(order.createdAt).toLocaleDateString('en-ZM', { day: 'numeric', month: 'short', year: 'numeric' })}</p></div><div className="flex items-center justify-between gap-5 sm:justify-end"><div className="text-left sm:text-right"><p className="font-mono text-sm font-bold">{money(order.total, order.currency)}</p><span data-testid={`status-order-${order.id}`} className="mt-1 inline-block rounded-full bg-secondary px-2.5 py-1 text-[10px] font-bold capitalize text-primary">{order.status}</span></div><ChevronRight size={17} className="text-muted-foreground transition-transform group-hover:translate-x-1" /></div></Link>)}</div> : <EmptyState icon={Package} title="No orders yet" copy="Your future favourites will live here once you place your first paid order." action={<Link href="/" data-testid="link-orders-shop" className="inline-flex rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Shop the shelves</Link>} />}</div>;
}

function SellPage() {
  const submit = useSubmitVendorApplication();
  const [form, setForm] = useState({ businessName: '', contactName: '', email: '', phone: '', category: '', description: '' });
  const [sent, setSent] = useState(false); const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setForm({ ...form, [key]: e.target.value });
  const send = (e: React.FormEvent) => { e.preventDefault(); setError(''); if (Object.values(form).some(v => !v.trim()) || form.description.length < 10 || form.phone.length < 7 || !form.email.includes('@')) { setError('Please complete each field with the requested details.'); return; } submit.mutate({ data: form }, { onSuccess: () => setSent(true), onError: () => setError('We could not send your application. Please try again.') }); };
  if (sent) return <div className="mx-auto max-w-2xl px-4 py-16 text-center sm:px-6"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-primary text-primary-foreground"><Check size={30} /></span><p className="mt-7 font-mono text-[10px] uppercase tracking-[.2em] text-accent">Application received</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">We will be in touch.</h1><p className="mx-auto mt-4 max-w-md text-sm leading-6 text-muted-foreground">Thanks for putting your business forward. Our team will review your details and get back to you shortly.</p><Link href="/" data-testid="link-sell-done" className="mt-7 inline-flex rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Back to Gulani</Link></div>;
  const input = (key: keyof typeof form, label: string, placeholder: string) => <label className="grid gap-2 text-xs font-bold">{label}<input data-testid={`input-vendor-${key}`} value={form[key]} onChange={update(key)} placeholder={placeholder} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" /></label>;
  return <div className="mx-auto max-w-6xl px-4 py-10 sm:px-6 lg:px-8"><div className="grid gap-12 lg:grid-cols-[.82fr_1.18fr] lg:items-start"><div className="lg:sticky lg:top-28"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">For local business</p><h1 className="mt-3 font-display text-5xl font-bold leading-[.96] tracking-[-.07em] sm:text-6xl">Your work belongs <span className="text-primary">here.</span></h1><p className="mt-6 max-w-md text-sm leading-7 text-muted-foreground">Gulani helps thoughtful Lusaka businesses reach people who want to shop local. Tell us what you make and we will take it from there.</p><div className="mt-10 space-y-4">{[['01', 'A considered storefront', 'Your products, presented with care.'], ['02', 'Customers who value local', 'Reach people already looking for what you do.'], ['03', 'A team in your corner', 'Simple tools and reliable operations.']].map(([n, t, c]) => <div key={n} className="flex gap-4"><span className="font-mono text-xs text-accent">{n}</span><div><p className="text-sm font-bold">{t}</p><p className="mt-1 text-xs text-muted-foreground">{c}</p></div></div>)}</div></div><form onSubmit={send} className="rounded-[26px] border border-border bg-card p-5 shadow-sm sm:p-8"><div className="flex items-center justify-between border-b border-border pb-5"><div><h2 className="font-display text-2xl font-bold">Vendor application</h2><p className="mt-1 text-xs text-muted-foreground">A few details to start a conversation.</p></div><Store className="text-primary" size={24} /></div>{error && <div data-testid="status-vendor-error" className="mt-5 rounded-xl bg-accent/10 p-3 text-xs font-semibold text-accent">{error}</div>}<div className="mt-7 grid gap-4 sm:grid-cols-2">{input('businessName', 'Business name', 'e.g. Chalo Ceramics')}{input('contactName', 'Your name', 'Who should we speak with?')}{input('email', 'Email address', 'hello@yourbusiness.com')}{input('phone', 'Phone number', '+260 97 000 0000')}{input('category', 'What do you sell?', 'Home, fashion, food…')}<div className="sm:col-span-2"><label className="grid gap-2 text-xs font-bold">Tell us about your business<textarea data-testid="input-vendor-description" value={form.description} onChange={update('description')} rows={5} placeholder="What makes your work special? What should customers know?" className="resize-none rounded-xl border border-input bg-background px-3 py-3 text-sm font-normal outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" /></label></div></div><button type="submit" data-testid="button-submit-vendor" disabled={submit.isPending} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground hover:brightness-110 disabled:opacity-60">{submit.isPending ? 'Sending application…' : <>Send application <ArrowRight size={16} /></>}</button><p className="mt-4 text-center text-[11px] leading-5 text-muted-foreground">By applying, you agree that Gulani can contact you about your application.</p></form></div></div>;
}

function Metric({ label, value, icon: Icon, tone = 'primary' }: { label: string; value: string | number; icon: typeof Package; tone?: 'primary' | 'accent' }) { return <div className="rounded-2xl border border-border bg-card p-5"><div className={`grid h-9 w-9 place-items-center rounded-xl ${tone === 'accent' ? 'bg-accent/15 text-accent' : 'bg-primary/10 text-primary'}`}><Icon size={18} /></div><p className="mt-5 font-mono text-2xl font-bold">{value}</p><p className="mt-1 text-xs text-muted-foreground">{label}</p></div>; }

function AccessState({ kind }: { kind: 'vendor' | 'admin' }) { return <div className="mx-auto max-w-2xl px-4 py-16 text-center sm:px-6"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-secondary text-primary"><ShieldCheck size={26} /></span><h1 className="mt-6 font-display text-3xl font-bold">{kind === 'vendor' ? 'Your vendor space is private' : 'Operations access required'}</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-muted-foreground">This surface is available to approved {kind === 'vendor' ? 'vendors' : 'Gulani operations teammates'}. If you think you should have access, contact the Gulani team.</p><Link href="/" data-testid={`link-${kind}-access-home`} className="mt-6 inline-flex rounded-full bg-primary px-5 py-3 text-xs font-bold text-primary-foreground">Back to storefront</Link></div>; }

function VendorPage() {
  const dashboard = useGetVendorDashboard({ query: { queryKey: getGetVendorDashboardQueryKey() } });
  if (dashboard.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><LoadingGrid /></div>;
  if (dashboard.isError || !dashboard.data) return <AccessState kind="vendor" />;
  const d = dashboard.data as VendorDashboard;
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="flex flex-wrap items-end justify-between gap-5"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Vendor portal</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">Good morning, {d.vendorName}.</h1><p className="mt-3 text-sm text-muted-foreground">Manage your products and orders from one place.</p></div><span className="flex items-center gap-2 rounded-full bg-secondary px-3 py-2 text-xs font-bold text-primary"><span className="h-2 w-2 rounded-full bg-primary" /> Store is live</span></div><div className="mt-9 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Pending orders" value={d.pendingOrders} icon={Clock3} tone="accent" /><Metric label="Products live" value={d.productsLive} icon={Package} /><Metric label="Revenue this month" value={money(d.revenueThisMonth)} icon={TrendingUp} /><Metric label="Store rating" value={d.rating.toFixed(1)} icon={Star} /></div><div className="mt-8 grid gap-7 lg:grid-cols-[1fr_300px]"><section><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Recent orders</h2><span className="font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Last 30 days</span></div>{d.recentOrders?.length ? <div className="space-y-3">{d.recentOrders.map(o => <Link key={o.id} href={`/order/${o.id}`} className="flex items-center gap-4 rounded-2xl border border-border bg-card p-4 hover:border-primary/40"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Package size={18} /></span><div className="min-w-0 flex-1"><p className="font-mono text-[10px] text-muted-foreground">{o.orderNumber}</p><p className="mt-1 truncate text-sm font-bold">{o.items.length} item order</p></div><div className="text-right"><p className="font-mono text-sm font-bold">{money(o.total, o.currency)}</p><p className="mt-1 text-[10px] capitalize text-primary">{o.status}</p></div><ChevronRight size={15} className="text-muted-foreground" /></Link>)}</div> : <EmptyState icon={Package} title="No recent orders" copy="New customer orders will appear here." />}</section><aside className="rounded-2xl bg-primary p-6 text-primary-foreground"><Sparkles size={21} className="text-accent" /><h2 className="mt-8 font-display text-2xl font-bold">Keep your shelf fresh.</h2><p className="mt-3 text-sm leading-6 text-primary-foreground/70">Clear photos and descriptions help shoppers choose with confidence.</p><Link href="/" className="mt-6 flex items-center gap-2 text-xs font-bold text-accent">Preview your storefront <ArrowRight size={14} /></Link></aside></div></div>;
}

function LegacyVendorPage() {
  const dashboard = useGetVendorDashboard({ query: { queryKey: getGetVendorDashboardQueryKey() } });
  if (dashboard.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><LoadingGrid /></div>;
  if (dashboard.isError) return <AccessState kind="vendor" />;
  const d = dashboard.data as VendorDashboard | undefined;
  if (!d) return <AccessState kind="vendor" />;
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div className="flex flex-wrap items-end justify-between gap-5"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Vendor portal</p><h1 data-testid="text-vendor-name" className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">Good morning, {d.vendorName}.</h1><p className="mt-3 text-sm text-muted-foreground">Here is what needs your attention today.</p></div><span className="flex items-center gap-2 rounded-full bg-secondary px-3 py-2 text-xs font-bold text-primary"><span className="h-2 w-2 rounded-full bg-primary" /> Store is live</span></div><div className="mt-9 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Pending orders" value={d.pendingOrders} icon={Clock3} tone="accent" /><Metric label="Products live" value={d.productsLive} icon={Package} /><Metric label="Revenue this month" value={money(d.revenueThisMonth)} icon={TrendingUp} /><Metric label="Store rating" value={d.rating.toFixed(1)} icon={Star} /></div><div className="mt-8 grid gap-7 lg:grid-cols-[1fr_300px]"><section><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Recent orders</h2><span className="font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Last 30 days</span></div>{d.recentOrders?.length ? <div className="space-y-3">{d.recentOrders.map(o => <Link key={o.id} href={`/order/${o.id}`} data-testid={`row-vendor-order-${o.id}`} className="flex items-center gap-4 rounded-2xl border border-border bg-card p-4 hover:border-primary/40"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Package size={18} /></span><div className="min-w-0 flex-1"><p className="font-mono text-[10px] text-muted-foreground">{o.orderNumber}</p><p className="mt-1 truncate text-sm font-bold">{o.items.length} item order</p></div><div className="text-right"><p className="font-mono text-sm font-bold">{money(o.total, o.currency)}</p><p className="mt-1 text-[10px] capitalize text-primary">{o.status}</p></div><ChevronRight size={15} className="text-muted-foreground" /></Link>)}</div> : <EmptyState icon={Package} title="No recent orders" copy="New customer orders will appear here." />}</section><aside className="rounded-2xl bg-primary p-6 text-primary-foreground"><Sparkles size={21} className="text-accent" /><h2 className="mt-8 font-display text-2xl font-bold">Keep your shelf fresh.</h2><p className="mt-3 text-sm leading-6 text-primary-foreground/70">Great product photos and clear descriptions help Lusaka shoppers choose with confidence.</p><Link href="/" data-testid="link-vendor-storefront" className="mt-6 flex items-center gap-2 text-xs font-bold text-accent">Preview your storefront <ArrowRight size={14} /></Link></aside></div></div>;
}

function AdminPage() {
  const dashboard = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey() } });
  if (dashboard.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><LoadingGrid /></div>;
  if (dashboard.isError) return <AccessState kind="admin" />;
  const d = dashboard.data as AdminDashboard | undefined;
  if (!d) return <AccessState kind="admin" />;
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Operations desk</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">The day, at a glance.</h1><p className="mt-3 text-sm text-muted-foreground">Keep the marketplace moving for every customer and vendor.</p></div><div className="mt-9 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Orders today" value={d.ordersToday} icon={ShoppingBag} /><Metric label="Sales today" value={money(d.salesToday)} icon={WalletCards} tone="accent" /><Metric label="Vendor applications" value={d.pendingVendorApplications} icon={Store} /><Metric label="Open support tickets" value={d.openSupportTickets} icon={CircleAlert} /></div><div className="mt-8 grid gap-7 lg:grid-cols-[1fr_1fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Queue health</p><h2 className="mt-2 font-display text-2xl font-bold">Fulfillment queues</h2></div><LayoutDashboard size={22} className="text-primary" /></div><div className="mt-7 space-y-4">{d.fulfillmentQueue?.map((queue, i) => <div key={queue.label}><div className="flex justify-between text-sm"><span className="font-semibold">{queue.label}</span><span data-testid={`text-queue-count-${i}`} className="font-mono font-bold text-primary">{queue.count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${i === 0 ? 'bg-accent' : 'bg-primary'}`} style={{ width: `${Math.min(100, Math.max(8, queue.count * 8))}%` }} /></div></div>)}</div>{!d.fulfillmentQueue?.length && <EmptyState icon={Check} title="Clear skies" copy="Nothing is waiting in the fulfillment queue." />}</section><section className="rounded-2xl bg-secondary p-5 sm:p-7"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Needs a human</p><h2 className="mt-2 font-display text-2xl font-bold">Keep an eye on</h2><div className="mt-7 grid gap-3">{[['Vendor applications', d.pendingVendorApplications, 'Review new local businesses'], ['Support tickets', d.openSupportTickets, 'Respond to customers'], ['Orders today', d.ordersToday, 'Watch delivery promises']].map(([label, count, copy]) => <div key={String(label)} className="flex items-center gap-4 rounded-xl border border-border/70 bg-background/60 p-4"><span className="font-display text-2xl font-bold text-primary">{count}</span><div><p className="text-sm font-bold">{label}</p><p className="mt-1 text-xs text-muted-foreground">{copy}</p></div><ChevronRight className="ml-auto text-muted-foreground" size={16} /></div>)}</div></section></div></div>;
}

const orderStatuses = ['PLACED', 'PAYMENT_CONFIRMED', 'PACKED', 'SOURCING', 'PURCHASED_FROM_SUPPLIER', 'IN_TRANSIT', 'CUSTOMS_CLEARANCE', 'RECEIVED_LOCAL_WAREHOUSE', 'SHIPPED', 'OUT_FOR_DELIVERY', 'DELIVERED', 'CANCELLED'] as const;
const vendorStatuses = ['pending', 'approved', 'rejected'] as const;
const ticketStatuses = ['open', 'in_progress', 'resolved'] as const;

function AdminNav({ section }: { section: string }) {
  const links = [
    { key: 'overview', label: 'Overview', href: '/admin', icon: LayoutDashboard },
    { key: 'orders', label: 'Orders', href: '/admin/orders', icon: ShoppingBag },
    { key: 'vendors', label: 'Vendor applications', href: '/admin/vendors', icon: Store },
    { key: 'tickets', label: 'Support tickets', href: '/admin/tickets', icon: Headphones },
    { key: 'fulfillment', label: 'Fulfillment', href: '/admin/fulfillment', icon: Truck },
    { key: 'sales', label: 'Sales', href: '/admin/sales', icon: CircleDollarSign },
    { key: 'pricing', label: 'Pricing rules', href: '/admin/pricing', icon: WalletCards },
    { key: 'settings', label: 'Settings', href: '/admin/settings', icon: Settings },
  ];
  return <nav className="mt-7 flex gap-2 overflow-x-auto border-b border-border pb-2">{links.map(({ key, label, href, icon: Icon }) => <Link key={key} href={href} className={`flex shrink-0 items-center gap-2 rounded-xl px-3 py-2.5 text-xs font-bold transition-colors ${section === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}`}><Icon size={15} />{label}</Link>)}</nav>;
}

function AdminOverviewView({ dashboard }: { dashboard: AdminDashboard }) {
  return <><div className="mt-8 grid gap-7 lg:grid-cols-[1fr_1fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Queue health</p><h2 className="mt-2 font-display text-2xl font-bold">Fulfillment queues</h2></div><LayoutDashboard size={22} className="text-primary" /></div><div className="mt-7 space-y-4">{dashboard.fulfillmentQueue?.map((queue, i) => <Link href="/admin/fulfillment" key={queue.label} className="block rounded-xl p-1 hover:bg-secondary/60"><div className="flex justify-between text-sm"><span className="font-semibold">{queue.label}</span><span className="font-mono font-bold text-primary">{queue.count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${i === 0 ? 'bg-accent' : 'bg-primary'}`} style={{ width: `${Math.min(100, Math.max(8, queue.count * 8))}%` }} /></div></Link>)}</div></section><section className="rounded-2xl bg-secondary p-5 sm:p-7"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Needs a human</p><h2 className="mt-2 font-display text-2xl font-bold">Keep an eye on</h2><div className="mt-7 grid gap-3"><Link href="/admin/vendors" className="flex items-center gap-4 rounded-xl border border-border/70 bg-background/60 p-4 hover:border-primary/40"><span className="font-display text-2xl font-bold text-primary">{dashboard.pendingVendorApplications}</span><div><p className="text-sm font-bold">Vendor applications</p><p className="mt-1 text-xs text-muted-foreground">Review new local businesses</p></div><ChevronRight className="ml-auto text-muted-foreground" size={16} /></Link><Link href="/admin/tickets" className="flex items-center gap-4 rounded-xl border border-border/70 bg-background/60 p-4 hover:border-primary/40"><span className="font-display text-2xl font-bold text-primary">{dashboard.openSupportTickets}</span><div><p className="text-sm font-bold">Support tickets</p><p className="mt-1 text-xs text-muted-foreground">Respond to customers</p></div><ChevronRight className="ml-auto text-muted-foreground" size={16} /></Link><Link href="/admin/orders" className="flex items-center gap-4 rounded-xl border border-border/70 bg-background/60 p-4 hover:border-primary/40"><span className="font-display text-2xl font-bold text-primary">{dashboard.ordersToday}</span><div><p className="text-sm font-bold">Orders today</p><p className="mt-1 text-xs text-muted-foreground">Watch delivery promises</p></div><ChevronRight className="ml-auto text-muted-foreground" size={16} /></Link></div></section></div></>;
}

function AdminOrdersView() {
  const orders = useListAdminOrders(undefined, { query: { queryKey: getListAdminOrdersQueryKey() } });
  const update = useUpdateAdminOrderStatus();
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('');
  const visible = (orders.data || []).filter(order => `${order.orderNumber} ${order.customerName} ${order.vendorName}`.toLowerCase().includes(search.toLowerCase()) && (!status || order.status === status));
  const changeStatus = (order: AdminOrder, nextStatus: typeof orderStatuses[number]) => update.mutate({ orderId: order.id, data: { status: nextStatus } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListAdminOrdersQueryKey() }) });
  return <section className="mt-8"><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="flex flex-1 items-center gap-2 rounded-xl border border-input bg-background px-3"><Search size={16} className="text-muted-foreground" /><input aria-label="Search orders" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search order, customer or vendor" className="h-11 min-w-0 flex-1 bg-transparent text-sm outline-none" /></div><select aria-label="Filter orders by status" value={status} onChange={e => setStatus(e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm"><option value="">All statuses</option>{orderStatuses.map(item => <option key={item} value={item}>{item.replaceAll('_', ' ')}</option>)}</select></div>{orders.isLoading ? <LoadingGrid /> : orders.isError ? <ErrorState retry={() => orders.refetch()} /> : <div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.1fr_1fr_.8fr_.8fr_1.15fr] gap-4 border-b border-border bg-secondary/50 px-5 py-3 font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground md:grid"><span>Order</span><span>Customer / vendor</span><span>Fulfillment</span><span>Total</span><span>Update status</span></div>{visible.map(order => <div key={order.id} className="grid gap-3 border-b border-border p-4 last:border-0 md:grid-cols-[1.1fr_1fr_.8fr_.8fr_1.15fr] md:items-center md:gap-4 md:px-5"><div><p className="font-mono text-xs font-bold">{order.orderNumber}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(order.placedAt).toLocaleString('en-ZM', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })} · {order.itemCount} items</p></div><div><p className="text-sm font-bold">{order.customerName}</p><p className="mt-1 text-xs text-muted-foreground">{order.vendorName}</p></div><div><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide">{order.fulfillment}</span></div><p className="font-mono text-sm font-bold">{money(order.total, order.currency)}</p><select aria-label={`Update ${order.orderNumber} status`} disabled={update.isPending} value={order.status} onChange={e => changeStatus(order, e.target.value as typeof orderStatuses[number])} className="h-10 rounded-lg border border-input bg-background px-2 text-xs"><option value={order.status}>{order.status.replaceAll('_', ' ')}</option>{orderStatuses.filter(item => item !== order.status).map(item => <option key={item} value={item}>{item.replaceAll('_', ' ')}</option>)}</select></div>)}{!visible.length && <EmptyState icon={ShoppingBag} title="No matching orders" copy="Try another search or clear the status filter." />}</div>}</section>;
}

function AdminVendorsView() {
  const applications = useListAdminVendorApplications(undefined, { query: { queryKey: getListAdminVendorApplicationsQueryKey() } });
  const update = useUpdateVendorApplicationStatus();
  const { toast } = useToast();
  const changeStatus = (application: AdminVendorApplication, status: typeof vendorStatuses[number]) => update.mutate({ applicationId: application.id, data: { status } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListAdminVendorApplicationsQueryKey() }); toast({ title: `Application ${status}`, description: application.businessName }); } });
  return <section className="mt-8">{applications.isLoading ? <LoadingGrid /> : applications.isError ? <ErrorState retry={() => applications.refetch()} /> : <div className="grid gap-4 lg:grid-cols-2">{(applications.data || []).map(application => <article key={application.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-start justify-between gap-3"><div><p className="font-display text-xl font-bold">{application.businessName}</p><p className="mt-1 text-xs text-muted-foreground">{application.category} · submitted {new Date(application.submittedAt).toLocaleDateString('en-ZM')}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide ${application.status === 'approved' ? 'bg-primary/10 text-primary' : application.status === 'rejected' ? 'bg-accent/15 text-accent' : 'bg-secondary text-muted-foreground'}`}>{application.status}</span></div><div className="mt-5 grid gap-2 text-xs"><p><strong>Contact:</strong> {application.contactName} · {application.phone}</p><p><strong>Email:</strong> {application.email}</p><p className="leading-5 text-muted-foreground">{application.description}</p></div><div className="mt-5 flex gap-2 border-t border-border pt-4">{application.status !== 'approved' && <button type="button" onClick={() => changeStatus(application, 'approved')} className="rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground">Approve</button>}{application.status !== 'rejected' && <button type="button" onClick={() => changeStatus(application, 'rejected')} className="rounded-lg border border-accent/40 px-3 py-2 text-xs font-bold text-accent">Reject</button>}{application.status !== 'pending' && <button type="button" onClick={() => changeStatus(application, 'pending')} className="rounded-lg border border-border px-3 py-2 text-xs font-bold">Move to pending</button>}</div></article>)}</div>}</section>;
}

function AdminTicketsView() {
  const tickets = useListSupportTickets(undefined, { query: { queryKey: getListSupportTicketsQueryKey() } });
  const update = useUpdateSupportTicket();
  const { toast } = useToast();
  const changeStatus = (ticket: SupportTicket, status: typeof ticketStatuses[number]) => update.mutate({ ticketId: ticket.id, data: { status, assignedTo: ticket.assignedTo || 'Operations desk' } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListSupportTicketsQueryKey() }); toast({ title: 'Ticket updated', description: ticket.subject }); } });
  return <section className="mt-8">{tickets.isLoading ? <LoadingGrid /> : tickets.isError ? <ErrorState retry={() => tickets.refetch()} /> : <div className="space-y-3">{(tickets.data || []).map(ticket => <article key={ticket.id} className="rounded-2xl border border-border bg-card p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-start gap-3"><span className={`mt-1 grid h-9 w-9 place-items-center rounded-xl ${ticket.priority === 'urgent' ? 'bg-accent/15 text-accent' : 'bg-secondary text-primary'}`}><Headphones size={17} /></span><div><p className="text-sm font-bold">{ticket.subject}</p><p className="mt-1 text-xs text-muted-foreground">{ticket.customerName} · {ticket.category} · {ticket.priority} priority</p></div></div><select aria-label={`Update ${ticket.subject} status`} value={ticket.status} disabled={update.isPending} onChange={e => changeStatus(ticket, e.target.value as typeof ticketStatuses[number])} className="h-9 rounded-lg border border-input bg-background px-2 text-xs font-bold"><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option></select></div><p className="mt-4 rounded-xl bg-secondary/60 p-3 text-xs leading-5 text-muted-foreground">{ticket.lastMessage}</p><p className="mt-3 text-[11px] text-muted-foreground">Assigned to: <strong className="text-foreground">{ticket.assignedTo || 'Unassigned'}</strong> · updated {new Date(ticket.updatedAt).toLocaleString('en-ZM', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</p></article>)}</div>}</section>;
}

function AdminFulfillmentView() {
  const fulfillment = useGetFulfillmentOverview({ query: { queryKey: getGetFulfillmentOverviewQueryKey() } });
  const update = useUpdateAdminOrderStatus();
  return <section className="mt-8">{fulfillment.isLoading ? <LoadingGrid /> : fulfillment.isError ? <ErrorState retry={() => fulfillment.refetch()} /> : <><div className="grid grid-cols-3 gap-3"><Metric label="Sourced orders" value={fulfillment.data?.sourcedOrders ?? 0} icon={Package} /><Metric label="Local orders" value={fulfillment.data?.localOrders ?? 0} icon={Store} /><Metric label="Needs attention" value={fulfillment.data?.delayedOrders ?? 0} icon={CircleAlert} tone="accent" /></div><div className="mt-7 space-y-4">{fulfillment.data?.queues.map(queue => <section key={queue.status} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">{queue.status}</p><h2 className="mt-1 font-display text-xl font-bold">{queue.label}</h2></div><span className="grid h-9 min-w-9 place-items-center rounded-full bg-secondary px-2 font-mono text-sm font-bold text-primary">{queue.count}</span></div>{queue.orders.length > 0 && <div className="mt-5 space-y-2">{queue.orders.map(order => <div key={order.id} className="flex flex-wrap items-center gap-3 rounded-xl bg-secondary/55 p-3"><div className="min-w-[140px] flex-1"><p className="font-mono text-xs font-bold">{order.orderNumber}</p><p className="mt-1 text-xs text-muted-foreground">{order.customerName} · {order.vendorName}</p></div><span className="font-mono text-xs font-bold">{money(order.total, order.currency)}</span><button type="button" onClick={() => { const next = orderStatuses[Math.min(orderStatuses.indexOf(order.status as typeof orderStatuses[number]) + 1, orderStatuses.length - 1)]; update.mutate({ orderId: order.id, data: { status: next } }, { onSuccess: () => fulfillment.refetch() }); }} className="rounded-lg border border-primary/30 px-3 py-2 text-xs font-bold text-primary hover:bg-primary hover:text-primary-foreground">Advance</button></div>)}</div>}</section>)}</div></>}</section>;
}

function AdminSalesView() {
  const sales = useGetSalesOverview({ query: { queryKey: getGetSalesOverviewQueryKey() } });
  const maxSales = Math.max(...(sales.data?.byDay.map(day => day.sales) || [1]));
  return <section className="mt-8">{sales.isLoading ? <LoadingGrid /> : sales.isError ? <ErrorState retry={() => sales.refetch()} /> : <><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Total sales" value={money(sales.data?.totalSales || 0)} icon={WalletCards} tone="accent" /><Metric label="Orders" value={sales.data?.totalOrders || 0} icon={ShoppingBag} /><Metric label="Average order value" value={money(sales.data?.averageOrderValue || 0)} icon={TrendingUp} /><Metric label="Platform commission" value={money(sales.data?.commission || 0)} icon={CircleDollarSign} /></div><div className="mt-7 grid gap-7 lg:grid-cols-[1.35fr_.65fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Sales trend</p><h2 className="mt-2 font-display text-2xl font-bold">The last seven days</h2><div className="mt-8 flex h-56 items-end gap-2 sm:gap-4">{sales.data?.byDay.map(day => <div key={day.label} className="flex min-w-0 flex-1 flex-col items-center gap-2"><span className="font-mono text-[9px] text-muted-foreground">{day.sales ? `${(day.sales / 1000).toFixed(1)}k` : '—'}</span><div className="flex h-40 w-full items-end rounded-t-lg bg-secondary"><div className="w-full rounded-t-lg bg-primary transition-all" style={{ height: `${day.sales ? Math.max(8, (day.sales / maxSales) * 100) : 0}%` }} /></div><span className="font-mono text-[10px] text-muted-foreground">{day.label}</span></div>)}</div></section><section className="rounded-2xl bg-secondary p-5 sm:p-7"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">By category</p><h2 className="mt-2 font-display text-2xl font-bold">Where sales land</h2><div className="mt-7 space-y-5">{sales.data?.byCategory.map(category => <div key={category.label}><div className="flex justify-between text-xs font-bold"><span>{category.label}</span><span className="font-mono">{money(category.sales)}</span></div><div className="mt-2 h-2 rounded-full bg-background"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(100, (category.sales / Math.max(1, sales.data?.totalSales || 1)) * 100 * 2.5)}%` }} /></div></div>)}</div></section></div></>}</section>;
}

function AdminSettingsView() {
  const settings = useGetAdminSettings({ query: { queryKey: getGetAdminSettingsQueryKey() } });
  const update = useUpdateAdminSettings();
  const { toast } = useToast();
  const [form, setForm] = useState<MarketplaceSettings | null>(null);
  useEffect(() => { if (settings.data) setForm(settings.data); }, [settings.data]);
  const set = <K extends keyof MarketplaceSettings>(key: K, value: MarketplaceSettings[K]) => setForm(current => current ? { ...current, [key]: value } : current);
  const save = (e: React.FormEvent) => { e.preventDefault(); if (!form) return; update.mutate({ data: form }, { onSuccess: saved => { setForm(saved); queryClient.invalidateQueries({ queryKey: getGetAdminSettingsQueryKey() }); toast({ title: 'Settings saved', description: 'Marketplace configuration is up to date.' }); } }); };
  if (settings.isLoading || !form) return <section className="mt-8"><LoadingGrid /></section>;
  if (settings.isError) return <section className="mt-8"><ErrorState retry={() => settings.refetch()} /></section>;
  return <form onSubmit={save} className="mt-8 max-w-4xl rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-start justify-between gap-4 border-b border-border pb-5"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">System configuration</p><h2 className="mt-2 font-display text-2xl font-bold">Marketplace settings</h2><p className="mt-2 text-sm text-muted-foreground">Changes apply to new checkout and vendor settlement calculations.</p></div><Settings size={23} className="text-primary" /></div><div className="mt-7 grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-xs font-bold">Store name<input value={form.storeName} onChange={e => set('storeName', e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Support email<input type="email" value={form.supportEmail} onChange={e => set('supportEmail', e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Default currency<input value={form.defaultCurrency} onChange={e => set('defaultCurrency', e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Delivery zone<input value={form.deliveryZone} onChange={e => set('deliveryZone', e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Standard delivery fee<input type="number" min="0" value={form.standardDeliveryFee} onChange={e => set('standardDeliveryFee', Number(e.target.value))} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Free delivery threshold<input type="number" min="0" value={form.freeDeliveryThreshold} onChange={e => set('freeDeliveryThreshold', Number(e.target.value))} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">VAT rate (%)<input type="number" min="0" max="100" value={form.vatRate} onChange={e => set('vatRate', Number(e.target.value))} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label><label className="grid gap-2 text-xs font-bold">Vendor commission (%)<input type="number" min="0" max="100" value={form.vendorCommissionRate} onChange={e => set('vendorCommissionRate', Number(e.target.value))} className="h-11 rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label></div><label className="mt-6 flex items-center gap-3 rounded-xl bg-secondary/60 p-4 text-sm font-bold"><input type="checkbox" checked={form.maintenanceMode} onChange={e => set('maintenanceMode', e.target.checked)} className="h-4 w-4 accent-primary" /> Put storefront in maintenance mode <span className="ml-auto text-xs font-normal text-muted-foreground">Stops new checkout</span></label><button type="submit" disabled={update.isPending} className="mt-7 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground hover:brightness-110 disabled:opacity-60">{update.isPending ? 'Saving…' : 'Save settings'}</button></form>;
}

function AdminPricingView() {
  const rules = useListPricingRules({ query: { queryKey: getListPricingRulesQueryKey() } });
  const update = useUpdatePricingRule();
  const { toast } = useToast();
  const [rates, setRates] = useState<Record<string, string>>({});
  useEffect(() => {
    if (rules.data) setRates(Object.fromEntries(rules.data.map(rule => [rule.id, String(rule.markupRate)])));
  }, [rules.data]);
  const saveRule = (rule: PricingRule) => {
    const markupRate = Number(rates[rule.id]);
    if (!Number.isFinite(markupRate) || markupRate < 0) {
      toast({ title: 'Enter a valid markup', description: 'Use a percentage of zero or more.', variant: 'destructive' });
      return;
    }
    update.mutate({ ruleId: rule.id, data: { markupRate, active: rule.active } }, {
      onSuccess: () => {
        queryClient.invalidateQueries({ queryKey: getListPricingRulesQueryKey() });
        toast({ title: 'Pricing rule saved', description: `${rule.label} now uses a ${markupRate}% markup.` });
      },
    });
  };
  return <section className="mt-8 max-w-4xl"><div className="rounded-2xl border border-primary/15 bg-primary/5 p-5 sm:p-7"><div className="flex items-start gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground"><CircleDollarSign size={19} /></span><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Source-aware pricing</p><h2 className="mt-2 font-display text-2xl font-bold">Control the customer price</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Imported products keep their supplier base price. On sync, Gulani applies the matching source rule before publishing the customer price.</p><p className="mt-4 rounded-xl bg-background/70 p-3 font-mono text-xs text-foreground">customer price = base price × (1 + markup ÷ 100)</p></div></div></div>{rules.isLoading ? <div className="mt-5"><LoadingGrid /></div> : rules.isError ? <div className="mt-5"><ErrorState retry={() => rules.refetch()} /></div> : <div className="mt-5 space-y-3">{(rules.data || []).map(rule => <article key={rule.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-display text-xl font-bold">{rule.label}</h3><span className="rounded-full bg-secondary px-2.5 py-1 font-mono text-[10px] font-bold uppercase tracking-wide">{rule.source === '*' ? 'fallback' : rule.source}</span></div><p className="mt-2 text-xs text-muted-foreground">Example: a 100 base-price item publishes at {money(100 * (1 + Number(rates[rule.id] ?? rule.markupRate) / 100))} before delivery.</p></div><div className="flex items-end gap-2"><label className="grid gap-2 text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Markup %<input type="number" min="0" max="500" value={rates[rule.id] ?? rule.markupRate} onChange={e => setRates(current => ({ ...current, [rule.id]: e.target.value }))} className="h-11 w-28 rounded-xl border border-input bg-background px-3 text-sm font-bold text-foreground outline-none focus:border-primary" /></label><button type="button" onClick={() => saveRule(rule)} disabled={update.isPending} className="h-11 rounded-xl bg-primary px-4 text-xs font-bold text-primary-foreground hover:brightness-110 disabled:opacity-60">Save</button></div></div></article>)}</div>}</section>;
}

function AdminDeskPage() {
  const [location] = useLocation();
  const section = location.split('/')[2] || 'overview';
  const dashboard = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey() } });
  if (dashboard.isLoading) return <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><LoadingGrid /></div>;
  if (dashboard.isError || !dashboard.data) return <AccessState kind="admin" />;
  return <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Master admin</p><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.06em]">{section === 'overview' ? 'The day, at a glance.' : ({ orders: 'All orders', vendors: 'Vendor applications', tickets: 'Support tickets', fulfillment: 'Sales fulfillment', sales: 'Sales overview', pricing: 'Pricing rules', settings: 'Marketplace settings' } as Record<string, string>)[section] || 'Operations'}</h1><p className="mt-3 text-sm text-muted-foreground">Manage products, sourcing, pricing, and marketplace operations.</p></div><AdminNav section={section} />{section === 'overview' && <><div className="mt-9 grid grid-cols-2 gap-3 lg:grid-cols-4"><Link href="/admin/orders"><Metric label="Orders today" value={dashboard.data.ordersToday} icon={ShoppingBag} /></Link><Link href="/admin/sales"><Metric label="Sales today" value={money(dashboard.data.salesToday)} icon={WalletCards} tone="accent" /></Link><Link href="/admin/vendors"><Metric label="Vendor applications" value={dashboard.data.pendingVendorApplications} icon={Store} /></Link><Link href="/admin/tickets"><Metric label="Open support tickets" value={dashboard.data.openSupportTickets} icon={CircleAlert} /></Link></div><AdminOverviewView dashboard={dashboard.data} /></>}{section === 'orders' && <AdminOrdersView />}{section === 'vendors' && <AdminVendorsView />}{section === 'tickets' && <AdminTicketsView />}{section === 'fulfillment' && <AdminFulfillmentView />}{section === 'sales' && <AdminSalesView />}{section === 'pricing' && <AdminPricingView />}{section === 'settings' && <AdminSettingsView />}</div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Shell><Switch><Route path="/" component={Home} /><Route path="/product/:id" component={ProductDetail} /><Route path="/cart" component={CartPage} /><Route path="/checkout" component={CheckoutPage} /><Route path="/order/:id" component={OrderPage} /><Route path="/orders" component={OrdersPage} /><Route path="/sell" component={SellPage} /><Route path="/vendor" component={VendorWorkspace} /><Route path="/store/:vendorId" component={PublicVendorStorefront} /><Route path="/admin" component={AdminDeskPage} /><Route path="/admin/orders" component={AdminDeskPage} /><Route path="/admin/vendors" component={AdminDeskPage} /><Route path="/admin/tickets" component={AdminDeskPage} /><Route path="/admin/fulfillment" component={AdminDeskPage} /><Route path="/admin/sales" component={AdminDeskPage} /><Route path="/admin/pricing" component={AdminDeskPage} /><Route path="/admin/settings" component={AdminDeskPage} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ScrollToTop /><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;